  memories: ClientReference<OperatorApi["memories"]>;
  facts: ClientReference<OperatorApi["facts"]>;
  factHistory: ClientReference<OperatorApi["factHistory"]>;
  conversations: ClientReference<OperatorApi["conversations"]>;
