    limit: { type: "integer", minimum: 1, maximum: 10 } }, required: ["text", "limit"], additionalProperties: false },
  memory_remember: { type: "object", properties: { text: { type: "string", minLength: 1, maxLength: 4096 } },
    required: ["text"], additionalProperties: false },
} as const);
export const NATIVE_TOOL_NAMES = Object.freeze({ "memory.recall": "memory_recall", "memory.remember": "memory_remember" } as const);
export const AGENT_NATIVE_TOOLS = Object.freeze([
  { type: "function", name: "memory_recall", description: "Recall authorized Cortex memory.", inputSchema: SERVER_TOOL_SCHEMAS.memory_recall },
  { type: "function", name: "memory_remember", description: "Remember explicit information in authorized Cortex memory.", inputSchema: SERVER_TOOL_SCHEMAS.memory_remember },
] as const);
/** V1 remains byte-stable for every previously published definition/proof. */
export const AGENT_TOOL_REGISTRY_VERSION_V2 = "cortex-media-tools-v2";
export const NATIVE_TOOL_NAMES_V2 = Object.freeze({ ...NATIVE_TOOL_NAMES,
  "media.image.generate": "media_image_generate", "media.video.generate": "media_video_generate", "artifact.read": "artifact_read" } as const);
export const AGENT_NATIVE_TOOLS_V2 = Object.freeze([...AGENT_NATIVE_TOOLS,
  { type: "function", name: "media_image_generate", description: "Create one governed image and return its durable job and artifact references.", inputSchema: { type: "object", properties: { prompt: { type: "string", minLength: 1, maxLength: 1024 } }, required: ["prompt"], additionalProperties: false } },
  { type: "function", name: "media_video_generate", description: "Create one governed video job and return its durable job and artifact references.", inputSchema: { type: "object", properties: { prompt: { type: "string", minLength: 1, maxLength: 1024 } }, required: ["prompt"], additionalProperties: false } },
  { type: "function", name: "artifact_read", description: "Read authorized artifact metadata and immutable asset references.", inputSchema: { type: "object", properties: { artifactId: { type: "string", minLength: 1, maxLength: 256 } }, required: ["artifactId"], additionalProperties: false } },
] as const);
export function agentToolCatalog(version: string) {
  return version === AGENT_TOOL_REGISTRY_VERSION ? AGENT_NATIVE_TOOLS : version === AGENT_TOOL_REGISTRY_VERSION_V2 ? AGENT_NATIVE_TOOLS_V2 : undefined;
}

/**
 * Conservative UTF8 ceiling over the complete canonical role/part/tool envelope.
 * Sixfold expansion covers JSON escaping/stringified tool arguments; the fixed
 * and per-message allowances cover the qualified native protocol framing. This
 * rule must be qualified with the exact native transform before it enables calls.
 */
export function agentToolsInputBound(canonicalPayload: string, messageCount: number, toolCount: number): number {
  const value = 6 * new TextEncoder().encode(canonicalPayload).length + 64 * (messageCount + toolCount) + 1024;
  if (!Number.isSafeInteger(value) || value < 1 || !Number.isSafeInteger(messageCount) || messageCount < 1
    || !Number.isSafeInteger(toolCount) || toolCount < 0 || toolCount > AGENT_NATIVE_TOOLS.length) throw new Error("INVALID_AGENT_INPUT_BOUND");
  return value;
}
export function agentToolsInputBoundV2(canonicalPayload: string, messageCount: number, toolCount: number): number {
  if (!Number.isSafeInteger(toolCount) || toolCount < 0 || toolCount > AGENT_NATIVE_TOOLS_V2.length) throw new Error("INVALID_AGENT_INPUT_BOUND");
  // Identical framing rule, independently pinned to the new five-tool catalog.
  return agentToolsInputBound(canonicalPayload, messageCount, Math.min(toolCount, AGENT_NATIVE_TOOLS.length)) + 64 * Math.max(0, toolCount - AGENT_NATIVE_TOOLS.length);
}

/** Private provenance of metadata consumed by a server tool; never observer input. */
export type ArtifactContextWitness = {
  version: 1;
  artifactId: string;
  artifactVersion: number;
  metadataHash: string;
};

/** Private immutable asset metadata. Binary bytes never enter transcript rows. */
export const ASSET_MAX_BYTES = 20_000_000;
export const ASSET_UPLOAD_LEASE_MS = 120_000;
export const ASSET_MIME_TYPES = ["image/png", "image/jpeg", "image/webp", "image/gif", "image/avif", "video/mp4", "video/webm", "audio/mpeg", "audio/ogg", "audio/wav", "audio/mp4", "audio/webm", "application/pdf", "application/octet-stream", "application/json", "text/plain", "text/csv"] as const;
export type RuntimeAssetMediaKind = "image" | "video" | "audio" | "document" | "binary";
export type RuntimeAssetLineage = { kind: "upload"; requestId: string } | { kind: "generated"; operationId: string; modelId: string; sourceVersionIds?: string[] };
export interface RuntimeAssetVersion {
  version: 1; assetId: string; versionId: string; assetVersion: number; contentHash: string;
  sizeBytes: number; mimeType: string; mediaKind: RuntimeAssetMediaKind; filename?: string; lineage: RuntimeAssetLineage;
}
export type RuntimeAssetVersionV1 = RuntimeAssetVersion;
export interface RuntimeAssetReference { assetId: string; version: number }
export function assetMediaKind(mime: string): RuntimeAssetMediaKind {
  if (!ASSET_MIME_TYPES.includes(mime as typeof ASSET_MIME_TYPES[number])) throw new Error("INVALID_ASSET_METADATA");
  return mime.startsWith("image/") ? "image" : mime.startsWith("video/") ? "video" : mime.startsWith("audio/") ? "audio" : mime === "application/octet-stream" ? "binary" : "document";
}
export function assertAssetSize(size: number, cap = ASSET_MAX_BYTES): void {
  if (!Number.isSafeInteger(cap) || cap < 1 || cap > ASSET_MAX_BYTES || !Number.isSafeInteger(size) || size < 1) throw new Error("INVALID_ASSET_METADATA");
  if (size > cap) throw new Error("ASSET_TOO_LARGE");
}
export async function assetContentHash(bytes: ArrayBuffer): Promise<string> {
  return Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)), byte => byte.toString(16).padStart(2, "0")).join("");
}
/** Count actual streamed bytes, including responses with dishonest/no length. */
export async function readBoundedAsset(stream: ReadableStream<Uint8Array>, cap = ASSET_MAX_BYTES): Promise<Uint8Array<ArrayBuffer>> {
  assertAssetSize(1, cap);
  const reader = stream.getReader(); const chunks: Uint8Array[] = []; let size = 0;
  try {
    while (true) { const next = await reader.read(); if (next.done) break; size += next.value.byteLength;
      if (size > cap) { await reader.cancel(); throw new Error("ASSET_TOO_LARGE"); } chunks.push(next.value); }
    assertAssetSize(size, cap); const bytes = new Uint8Array(size); let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; } return bytes;
  } finally { reader.releaseLock(); }
}

/** Ordered conflict plans are data; only the scoped native mutation can commit them. */
import type { AttributedFact, DerivedFact, SourceContent } from "./contracts";
import type { ConflictDecision } from "./conflicts";
import { validateConflictDecision } from "./conflicts";
import { semanticHash } from "./profile";
import { BELIEF_POLICY_VERSION, MAX_INGESTION_FACTS } from "./ingestion";
import { canonicalModelJson } from "./model_policy";
export interface BeliefPlanEntry { ordinal: number; slotKey: string; candidate: AttributedFact;
  decision: ConflictDecision; targetFactId: string | null; next?: DerivedFact }
export interface BeliefPlanV1 { version: 1; eventId: string; sequence: number; sourceHash: string;
  expectedVersions: Record<string, number>; entries: BeliefPlanEntry[] }
export function beliefSlot(fact: Pick<AttributedFact, "subject" | "predicate" | "fact">): string {
  return JSON.stringify(fact.subject && fact.predicate ? [fact.subject.trim().toLowerCase(), fact.predicate.trim().toLowerCase()]
    : ["text", fact.fact.trim().toLowerCase()]);
}
export async function planBeliefs(input: { eventId: string; sequence: number; source: SourceContent;
  candidates: readonly AttributedFact[]; existing: readonly DerivedFact[];
  resolve(candidate: AttributedFact, existing: readonly DerivedFact[], ordinal: number): Promise<ConflictDecision> }): Promise<BeliefPlanV1> {
  if (!Number.isSafeInteger(input.sequence) || input.sequence < 1 || input.candidates.length > MAX_INGESTION_FACTS
    || input.existing.length > MAX_INGESTION_FACTS || input.source.lineage.role === "assistant") throw new Error("INVALID_BELIEF_PLAN");
  const expectedVersions = Object.fromEntries(input.existing.map(fact => [fact.factId, fact.version]));
  const entries: BeliefPlanEntry[] = []; const virtual = new Map(input.existing.map(fact => [fact.factId, fact]));
  const used = new Set<string>();
  for (const [ordinal, candidate] of input.candidates.entries()) {
    if (canonicalModelJson(candidate.lineage) !== canonicalModelJson(input.source.lineage)) throw new Error("INVALID_BELIEF_PLAN");
    const slotKey = canonicalModelJson([input.source.ownerPrincipalId, beliefSlot(candidate)]);
    // Multiple same-slot candidates in one extraction must be resolved by extraction, not two independent writes to one read version.
    if (used.has(slotKey)) throw new Error("AMBIGUOUS_EXTRACTION_SLOT"); used.add(slotKey);
    const matching = [...virtual.values()].filter(fact => fact.ownerPrincipalId === input.source.ownerPrincipalId && beliefSlot(fact) === beliefSlot(candidate) && !fact.supersededBy);
    const decision = matching.length ? await input.resolve(candidate, matching, ordinal)
      : { action: "ADD" as const, targetFactId: null, mergedFact: null, reason: "No current matching belief" };
    if (!validateConflictDecision(decision, matching).valid || (decision.action === "NONE" && !decision.targetFactId)
      || (decision.action === "ADD" && decision.targetFactId !== null)) throw new Error("INVALID_BELIEF_DECISION");
    const target = decision.targetFactId ? virtual.get(decision.targetFactId) : undefined;
    const id = decision.action === "UPDATE" ? target!.factId : await semanticHash(JSON.stringify([input.eventId, BELIEF_POLICY_VERSION, ordinal, candidate.fact]));
    const entry: BeliefPlanEntry = { ordinal, slotKey, candidate, decision, targetFactId: decision.targetFactId };
    if (decision.action !== "NONE") {
      entry.next = { _id: "", factId: id, tenantId: input.source.tenantId, memorySpaceId: input.source.memorySpaceId,
        ownerPrincipalId: input.source.ownerPrincipalId, lineage: input.source.lineage, extractionPolicyVersion: BELIEF_POLICY_VERSION,
        fact: decision.action === "UPDATE" ? decision.mergedFact! : candidate.fact, factType: candidate.factType,
        ...(candidate.subject ? { subject: candidate.subject } : {}), ...(candidate.predicate ? { predicate: candidate.predicate } : {}),
        ...(candidate.object ? { object: candidate.object } : {}), confidence: candidate.confidence * 100,
        tags: candidate.tags ?? [], entities: candidate.entities ?? [], relations: candidate.relations ?? [],
        sourceType: input.source.lineage.role === "tool" ? "tool" : "conversation", version: decision.action === "UPDATE" ? target!.version + 1 : 1,
        createdAt: target && decision.action === "UPDATE" ? target.createdAt : input.source.createdAt, updatedAt: input.source.createdAt,
        ...(decision.action === "SUPERSEDE" ? { supersedes: target!.factId } : {}) };
      if (decision.action === "SUPERSEDE") virtual.delete(target!.factId);
      virtual.set(id, entry.next); if (!(id in expectedVersions)) expectedVersions[id] = 0;
    }
    entries.push(entry);
  }
  return { version: 1, eventId: input.eventId, sequence: input.sequence, sourceHash: input.source.contentHash, expectedVersions, entries };
}

