  if(!["http:","https:"].includes(url.protocol)||url.username||url.password||url.search||url.hash||url.pathname!=="/"||typeof options.deploymentKey!=="string"||!options.deploymentKey.trim())
    throw new GraphDatabaseError("Pass explicit deployment URL and administrator key for graph erasure.","GRAPH_ERASURE_TRANSPORT_REQUIRED");
  const active=new Set<AbortController>();let closed=false,current:GraphRebuildRequestOptions|undefined,inFlight=false;
  // Same bounded HTTP body/cancellation primitive as the two-function rebuild transport.
  const guardedFetch:typeof fetch=async(input,init={})=>{
    const controller=new AbortController(),timeout=current?.timeoutMs??30000,signal=current?.signal;
    if(closed||!Number.isFinite(timeout)||timeout<=0||signal?.aborted)throw new GraphDatabaseError("Graph erasure request cancelled.","GRAPH_ERASURE_CANCELLED");
    active.add(controller);const cancel=()=>controller.abort();signal?.addEventListener("abort",cancel,{once:true});const timer=setTimeout(cancel,Math.min(timeout,30000));
    try {
      const response=await fetch(input,{...init,signal:controller.signal}),reader=response.body?.getReader(),chunks:Uint8Array[]=[];let bytes=0;
      if(reader)try{for(;;){const item=await reader.read();if(item.done)break;bytes+=item.value.byteLength;if(bytes>8*1024*1024)throw new GraphDatabaseError("Graph erasure response exceeded its encoded bound.","GRAPH_ERASURE_PAGE_BUDGET");chunks.push(item.value);}}
      finally{try{await reader.cancel();}finally{reader.releaseLock();}}
      const joined=new Uint8Array(bytes);let offset=0;for(const chunk of chunks){joined.set(chunk,offset);offset+=chunk.byteLength;}
      return new Response(joined,{status:response.status,statusText:response.statusText,headers:response.headers});
    }finally{clearTimeout(timer);signal?.removeEventListener("abort",cancel);active.delete(controller);}
  };
  const candidate:unknown=new ConvexHttpClient(url.origin,{logger:false,fetch:guardedFetch});
  if(!candidate||typeof candidate!=="object"||!("setAdminAuth"in candidate)||typeof candidate.setAdminAuth!=="function"||!("mutation"in candidate)||typeof candidate.mutation!=="function")
    throw new GraphDatabaseError("Installed Convex client lacks the fixed administrator transport.","GRAPH_ERASURE_TRANSPORT_REQUIRED");
  const client=candidate as {setAdminAuth(key:string):void;mutation(reference:FunctionReference<"mutation">,args:Record<string,unknown>,options:{skipQueue:true}):Promise<unknown>};client.setAdminAuth(options.deploymentKey);
  const selection=(item:GraphErasureItem)=>{
    identityProperties(item.identity);const table=Object.entries(GRAPH_TABLES).find(([,kind])=>kind===item.identity.kind)![0];
    return {table,physicalSourceId:item.identity.physicalSourceId,sourceRevision:item.sourceRevision,ownershipRevision:item.ownershipRevision,referenceRevision:item.referenceRevision,referenceGeneration:item.referenceGeneration,targetId:item.evidence.targetId};
  };
  const call=async(item:GraphErasureItem,mode:Record<string,unknown>,request?:GraphRebuildRequestOptions)=>{
    if(closed||inFlight)throw new GraphDatabaseError("Graph erasure transport closed or already active.","GRAPH_ERASURE_TRANSPORT_BUSY");
    const args={tenantId:item.identity.tenantId??undefined,disposal:{...selection(item),...mode}};inFlight=true;current=request;
    try{return await client.mutation(makeFunctionReference("cliOperator/graphSync:clearSyncedItems"),args,{skipQueue:true});}
    catch(error){if(error instanceof ConvexError||error instanceof GraphDatabaseError)throw error;throw new GraphDatabaseError("Original graph disposal response is unresolved; read status before continuing.",request?.signal?.aborted?"GRAPH_ERASURE_CANCELLED":"GRAPH_ERASURE_RESPONSE_UNKNOWN");}
    finally{inFlight=false;current=undefined;}
  };
  return {preflight:(item,scan,range,request)=>call(item,{kind:"preflight",scan,range},request),status:(item,receipt,request)=>call(item,{kind:"status",id:receipt.id,generation:receipt.generation},request),
    dispose:(item,receipt,expectedDisposalRevision,request)=>call(item,{kind:"dispose",id:receipt.id,generation:receipt.generation,expectedDisposalRevision},request),
    close:()=>{closed=true;for(const controller of active)controller.abort();}};
}

/** Fixed managed identities. Logical IDs are display properties, never source authority. */
import { createSha256 } from "../common/crypto";
import { convexToJson, type Value } from "convex/values";
import { GraphDatabaseError } from "./types";
import type { GraphIdentity, GraphKind, GraphJob, GraphScope } from "./types";

export const GRAPH_TABLES = {
  memories: "Memory", facts: "Fact", contexts: "Context",
  conversations: "Conversation", memorySpaces: "MemorySpace",
  immutable: "Immutable", mutable: "Mutable", artifacts: "Artifact",
} as const;
export const MANAGED_KINDS = [
  ...Object.values(GRAPH_TABLES), "User", "Agent", "Participant", "Entity", "SourceState",
] as const;
export const MANAGED_LABELS = Object.fromEntries(
  MANAGED_KINDS.map((kind) => [kind, `CortexV2${kind}`]),
) as Record<(typeof MANAGED_KINDS)[number], string>;
export const MANAGED_RELATIONSHIPS = [
  "IN_SPACE", "CHILD_OF", "TRIGGERED_BY", "GRANTS_ACCESS_TO", "REFERENCES",
  "SOURCED_FROM", "PART_OF", "EXTRACTED_FROM", "SUPERSEDES", "SUPERSEDED_BY",
  "INVOLVES", "RELATES_TO", "HAS_PARTICIPANT", "STORED_BY", "EXTRACTED_BY",
  "MENTIONS", "ENTITY_RELATION", "ARTIFACT_MEMORY", "ARTIFACT_CONVERSATION",
] as const;

function sorted(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sorted);
  if (value && typeof value === "object") return Object.fromEntries(
    Object.entries(value).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0)
      .map(([key, item]) => [key, sorted(item)]),
  );
  return value;
}
export const canonicalGraphJson = (value: Value): string =>
  JSON.stringify(sorted(convexToJson(value)));
export const graphDigest = (value: Value): string =>
  createSha256().update(canonicalGraphJson(value)).digestHex();
export const graphBytes = (value: Value): number => new TextEncoder().encode(canonicalGraphJson(value)).length;
const stringOrNull = (value: unknown): value is string | null => value === null || typeof value === "string";

export function primaryGraphIdentity(
  kind: GraphKind, physicalSourceId: string, scope: GraphScope,
): GraphIdentity {
  if (!Object.values(GRAPH_TABLES).includes(kind) || typeof physicalSourceId !== "string" || !physicalSourceId ||
      scope.tenantKnown !== true || !stringOrNull(scope.tenantId) || !stringOrNull(scope.memorySpaceId))
    throw new GraphDatabaseError("A managed graph operation needs captured physical identity and exact known scope.", "GRAPH_IDENTITY_REQUIRED");
  const spaceApplicable = kind !== "Immutable" && kind !== "Mutable";
  if (spaceApplicable !== (scope.memorySpaceId !== null))
    throw new GraphDatabaseError("Graph source space applicability does not match its fixed kind.", "GRAPH_SCOPE_MISMATCH");
  const tuple = ["cortex.graph.v2", scope.tenantId === null ? ["knownTenantless"] : ["tenant", scope.tenantId],
    kind, scope.memorySpaceId === null ? ["spaceNotApplicable"] : ["space", scope.memorySpaceId], physicalSourceId];
  return { schemaVersion: 2, key: graphDigest(tuple), tupleJson: canonicalGraphJson(tuple), kind,
    physicalSourceId, tenantKnown: true, tenantId: scope.tenantId, memorySpaceId: scope.memorySpaceId };
}
export function identityProperties(identity: GraphIdentity): Record<string, string | number | boolean> {
  const expected = primaryGraphIdentity(identity.kind, identity.physicalSourceId, identity);
  if (expected.key !== identity.key || expected.tupleJson !== identity.tupleJson || identity.schemaVersion !== 2)
    throw new GraphDatabaseError("Graph identity key and exact tuple disagree.", "GRAPH_IDENTITY_MISMATCH");
  return { key: identity.key, schemaVersion: 2, tupleJson: identity.tupleJson,
    kind: identity.kind, physicalSourceId: identity.physicalSourceId,
    tenantTag: identity.tenantId === null ? "knownTenantless" : "tenant", tenantValue: identity.tenantId ?? "",
    spaceTag: identity.memorySpaceId === null ? "spaceNotApplicable" : "space", spaceValue: identity.memorySpaceId ?? "" };
}
export function assertIdentityProperties(actual: Record<string, unknown>, identity: GraphIdentity): void {
  for (const [key, value] of Object.entries(identityProperties(identity)))
    if (actual[key] !== value) throw new GraphDatabaseError("Managed graph key/tuple mismatch; no legacy node may be adopted.", "GRAPH_IDENTITY_MISMATCH");
}
export function derivedGraphIdentity(kind: "User" | "Agent" | "Participant" | "Entity", logicalId: string,
  scope: GraphScope, entityType?: string): {key: string; tupleJson: string; properties: Record<string, Value>} {
  if (scope.tenantKnown !== true || !stringOrNull(scope.tenantId) || typeof logicalId !== "string" || !logicalId ||
      (kind === "Entity" && (typeof scope.memorySpaceId !== "string" || typeof entityType !== "string")))
    throw new GraphDatabaseError("Derived graph identity requires exact scope.", "GRAPH_IDENTITY_REQUIRED");
  const name = kind === "Entity" ? logicalId.trim().toLowerCase() : logicalId;
  if (!name) throw new GraphDatabaseError("Derived graph identity cannot be empty.", "GRAPH_IDENTITY_REQUIRED");
  const tuple = ["cortex.graph.v2.derived", scope.tenantId === null ? ["knownTenantless"] : ["tenant", scope.tenantId], kind,
    kind === "Entity" ? ["space", scope.memorySpaceId ?? "", name, entityType ?? ""] : ["logical", name]];
  const key = graphDigest(tuple), tupleJson = canonicalGraphJson(tuple);
  return { key, tupleJson, properties: {key, tupleJson, schemaVersion: 2, kind, logicalId: name,
    tenantTag: scope.tenantId === null ? "knownTenantless" : "tenant", tenantValue: scope.tenantId ?? "",
    spaceTag: kind === "Entity" ? "space" : "spaceNotApplicable", spaceValue: kind === "Entity" ? scope.memorySpaceId : "",
    ...(kind === "Entity" ? {name, type: entityType!} : {})} };
}
/** Target content revisions are delivery preconditions, not changes to the source payload/physical binding. */
export function graphSourceDigest(projection: import("./types").GraphProjection): string {
  return graphDigest({...projection,references:projection.references.map(({sourceRevision: _targetRevision,...binding})=>binding)} as unknown as Value);
}
function validateGraphJobEvidence(job: GraphJob): GraphJob {
  identityProperties(job.identity);
  if (job.sourceDigest !== undefined && job.sourceDigest !== graphSourceDigest(job.projection))
    throw new GraphDatabaseError("Captured source fingerprint contradicts its physical projection.", "GRAPH_JOB_UNRESOLVED");
  if (job.schemaVersion !== 2 || GRAPH_TABLES[job.table] !== job.identity.kind || !job._id || !job.generation || !job.attemptToken ||
      !Number.isSafeInteger(job.sourceRevision) || job.sourceRevision < 1 ||
      !["insert", "update", "delete"].includes(job.operation) || job.projection.sourceRevision !== job.sourceRevision ||
      job.projection.identity.key !== job.identity.key || job.projection.identity.tupleJson !== job.identity.tupleJson ||
      !job.referenceGeneration || !Number.isSafeInteger(job.ownershipRevision) || job.ownershipRevision < 1)
    throw new GraphDatabaseError("The immutable graph job has missing or contradictory captured evidence.", "GRAPH_JOB_UNRESOLVED");
  const expectedDigest = graphDigest({request:{graphInvocationId:job.graphInvocationId,priority:job.priority??"normal"},table:job.table,operation:job.operation,projection:job.projection,...job.sourceDigest===undefined?{}:{sourceDigest:job.sourceDigest},...job.suppressedJobs===undefined?{}:{suppressedJobs:job.suppressedJobs}} as unknown as Value);
  if (job.projectionJson !== undefined || job.projectionDigest !== undefined || job.requestJson !== undefined) {
    const request = {request:{graphInvocationId:job.graphInvocationId,priority:job.priority??"normal"},table:job.table,operation:job.operation,projection:job.projection,...job.sourceDigest===undefined?{}:{sourceDigest:job.sourceDigest},...job.suppressedJobs===undefined?{}:{suppressedJobs:job.suppressedJobs}};
    if (job.projectionJson !== canonicalGraphJson(job.projection as unknown as Value) ||
        job.requestJson !== canonicalGraphJson(request as unknown as Value) ||
        job.projectionDigest !== createSha256().update(job.projectionJson).digestHex() ||
        job.requestDigest !== createSha256().update(job.requestJson).digestHex())
      throw new GraphDatabaseError("Native canonical projection evidence is contradictory.", "GRAPH_JOB_UNRESOLVED");
  }
  if (job.requestDigest !== expectedDigest)
    throw new GraphDatabaseError("Graph job digest is contradictory.", "GRAPH_JOB_UNRESOLVED");
  if (graphBytes(job.projection as unknown as Value) > 256 * 1024)
    throw new GraphDatabaseError("Graph projection exceeds the inline native limit.", "GRAPH_PROJECTION_BUDGET");
  return job;
}

/** Malformed external evidence must refuse with a typed unresolved result before graph effects. */
export function validateGraphJob(job: GraphJob): GraphJob {
  try {return validateGraphJobEvidence(job);}
  catch(error) {if(error instanceof GraphDatabaseError)throw error;throw new GraphDatabaseError("Captured graph job evidence is malformed.","GRAPH_JOB_UNRESOLVED");}
}

/** Fixed administrator transport. It never consults environment/config or exposes an ordinary Cortex client. */
import {ConvexHttpClient} from "convex/browser";
import {makeFunctionReference,type FunctionReference} from "convex/server";
import {ConvexError} from "convex/values";
import type {GraphKind} from "./types";
import {GraphDatabaseError} from "./types";
import {GRAPH_TABLES} from "./identity";
export interface GraphRebuildSelection {tenantId?:string;memorySpaceId?:string;}
export interface GraphRebuildRange {cursor:string|null;endCursor:string|null;numItems:number;}
export interface GraphRebuildRequestOptions {signal?:AbortSignal;timeoutMs?:number;}
export interface GraphRebuildSourceRequest extends GraphRebuildSelection {version:2;kind:GraphKind;paginationOpts:GraphRebuildRange;}
export interface GraphRebuildEdgeRequest extends GraphRebuildSourceRequest {physicalSourceId:string;expectedSourceRevision:number;expectedOwnershipRevision:number;expectedReferenceGeneration:string;}
export interface GraphRebuildTransport {
  sourcePage(args:GraphRebuildSourceRequest,options?:GraphRebuildRequestOptions):Promise<unknown>;
  edgePage(args:GraphRebuildEdgeRequest,options?:GraphRebuildRequestOptions):Promise<unknown>;
  /** Abort only requests owned by this transport; no graph adapter or Cortex ownership. */
  close():void;
}
export function createGraphRebuildTransport(options:{url:string;deploymentKey:string}):GraphRebuildTransport {
  const url=new URL(options.url);
  if(!["http:","https:"].includes(url.protocol)||url.username||url.password||url.search||url.hash||url.pathname!=="/"||
    typeof options.deploymentKey!=="string"||!options.deploymentKey.trim())throw new GraphDatabaseError("An explicit deployment URL and administrator key are required for graph rebuild.","GRAPH_REBUILD_TRANSPORT_REQUIRED");
  const active=new Set<AbortController>();let closed=false,current:GraphRebuildRequestOptions|undefined;
  const guardedFetch:typeof fetch=async(input,init={})=>{
    const controller=new AbortController(),timeout=current?.timeoutMs??30000,signal=current?.signal;
    if(closed||!Number.isFinite(timeout)||timeout<=0||signal?.aborted)throw new GraphDatabaseError("Graph rebuild was cancelled or its deadline expired.","GRAPH_REBUILD_CANCELLED");
    active.add(controller);const cancel=()=>controller.abort();signal?.addEventListener("abort",cancel,{once:true});
    const timer=setTimeout(cancel,Math.min(timeout,30000));
    try {
      const response=await fetch(input,{...init,signal:controller.signal}),reader=response.body?.getReader(),chunks:Uint8Array[]=[];let bytes=0;
      if(reader)try {for(;;){const item=await reader.read();if(item.done)break;bytes+=item.value.byteLength;if(bytes>8*1024*1024)throw new GraphDatabaseError("Native graph rebuild response exceeds its encoded bound.","GRAPH_REBUILD_PAGE_BUDGET");chunks.push(item.value);}}
      finally {try{await reader.cancel();}finally{reader.releaseLock();}}
      const joined=new Uint8Array(bytes);let offset=0;for(const chunk of chunks){joined.set(chunk,offset);offset+=chunk.byteLength;}
      return new Response(joined,{status:response.status,statusText:response.statusText,headers:response.headers});
    }finally{clearTimeout(timer);signal?.removeEventListener("abort",cancel);active.delete(controller);}
  };
  const candidate:unknown=new ConvexHttpClient(url.origin,{logger:false,fetch:guardedFetch});
  if(!candidate||typeof candidate!=="object"||!("setAdminAuth"in candidate)||typeof candidate.setAdminAuth!=="function"||!("query"in candidate)||typeof candidate.query!=="function")
    throw new GraphDatabaseError("The installed Convex client does not support the fixed administrator transport.","GRAPH_REBUILD_TRANSPORT_REQUIRED");
  const client=candidate as {setAdminAuth(key:string):void;query(reference:FunctionReference<"query">,args:Record<string,unknown>):Promise<unknown>};
  client.setAdminAuth(options.deploymentKey);
  let inFlight=false;
  const call=async(name:"rebuildSourcePage"|"rebuildEdgePage",args:GraphRebuildSourceRequest|GraphRebuildEdgeRequest,request?:GraphRebuildRequestOptions)=>{
    if(closed||inFlight)throw new GraphDatabaseError("Graph rebuild transport is closed or already has an active request.","GRAPH_REBUILD_TRANSPORT_BUSY");
    if(args.version!==2||!Object.values(GRAPH_TABLES).includes(args.kind)||args.tenantId!==undefined&&(typeof args.tenantId!=="string"||!args.tenantId)||
      args.memorySpaceId!==undefined&&(typeof args.memorySpaceId!=="string"||!args.memorySpaceId))throw new GraphDatabaseError("Graph rebuild requires fixed kind and exact known scope.","GRAPH_SCOPE_MISMATCH");
    inFlight=true;current=request;
    try{return await client.query(makeFunctionReference(`cliOperator/graphSync:${name}`),args as unknown as Record<string,unknown>);}
    catch(error){if(error instanceof ConvexError||error instanceof GraphDatabaseError)throw error;throw new GraphDatabaseError("Fixed native graph rebuild request failed; confirmed counts remain partial.",request?.signal?.aborted?"GRAPH_REBUILD_CANCELLED":"GRAPH_REBUILD_TRANSPORT_FAILED");}
    finally{inFlight=false;current=undefined;}
  };
  return {sourcePage:(args,request)=>call("rebuildSourcePage",args,request),edgePage:(args,request)=>call("rebuildEdgePage",args,request),close:()=>{closed=true;for(const controller of active)controller.abort();}};
}

/** Explicit, fixed managed-v2 schema. Existing legacy/custom schema is never adopted or dropped. */
import type { GraphAdapter } from "../types";
import { GraphDatabaseError } from "../types";
import { MANAGED_KINDS, MANAGED_LABELS } from "../identity";

const names = MANAGED_KINDS.map(kind => ({kind, label: MANAGED_LABELS[kind],
  name: `cortex_v2_${kind.toLowerCase()}_key`, scope: `cortex_v2_${kind.toLowerCase()}_scope`}));
const list = (value: unknown): string[] => Array.isArray(value) ? value.map(String) : [];
async function inspect(adapter: GraphAdapter) {
  const dialect = await adapter.managedDialect?.();
  if (!adapter.managedRead) throw new GraphDatabaseError("Adapter requires bounded managed reads.", "GRAPH_SCHEMA_MIGRATION_REQUIRED");
  if (!dialect) throw new GraphDatabaseError("This adapter needs managed-v2 dialect support. Upgrade the adapter and explicitly initialize/rebuild.", "GRAPH_SCHEMA_MIGRATION_REQUIRED");
  const constraints = (await adapter.managedRead(dialect === "neo4j" ?
    "SHOW CONSTRAINTS YIELD name, type, entityType, labelsOrTypes, properties RETURN *" : "SHOW CONSTRAINT INFO")).records;
  const indexes = (await adapter.managedRead(dialect === "neo4j" ?
    "SHOW INDEXES YIELD name, type, entityType, labelsOrTypes, properties, state, owningConstraint RETURN *" : "SHOW INDEX INFO")).records;
  return {dialect, constraints, indexes};
}
function constraintMatches(r: Record<string, unknown>, label: string, dialect: string) {
  // Neo4j 5 reports UNIQUENESS; Cypher 25 names the same node constraint NODE_PROPERTY_UNIQUENESS.
  return dialect === "neo4j" ? (r.type === "UNIQUENESS" || r.type === "NODE_PROPERTY_UNIQUENESS") && r.entityType === "NODE" &&
    JSON.stringify(list(r.labelsOrTypes)) === JSON.stringify([label]) && JSON.stringify(list(r.properties)) === '["key"]' :
    r["constraint type"] === "unique" && r.label === label && JSON.stringify(list(r.properties)) === '["key"]';
}
function indexMatches(r: Record<string, unknown>, label: string, property: string, dialect: string) {
  return dialect === "neo4j" ? r.entityType === "NODE" && r.state === "ONLINE" &&
    JSON.stringify(list(r.labelsOrTypes)) === JSON.stringify([label]) && JSON.stringify(list(r.properties)) === JSON.stringify([property]) :
    r.label === label && JSON.stringify(list(r.property)) === JSON.stringify([property]) && r["index type"] === "label+property";
}
export async function verifyGraphSchema(adapter: GraphAdapter): Promise<{valid: boolean; constraints: string[]; indexes: string[]; missing: string[]}> {
  const actual = await inspect(adapter), missing: string[] = [];
  for (const item of names) {
    if (actual.dialect === "neo4j") {
      const named = actual.constraints.find(r => r.name === item.name);
      if (named && !constraintMatches(named, item.label, actual.dialect))
        throw new GraphDatabaseError("A fixed managed schema name has a conflicting definition.", "GRAPH_SCHEMA_CONFLICT");
      const scope = actual.indexes.find(r => r.name === item.scope);
      if (scope && !indexMatches(scope, item.label, "tenantValue", actual.dialect))
        throw new GraphDatabaseError("A fixed managed scope index has a conflicting definition.", "GRAPH_SCHEMA_CONFLICT");
    }
    if (!actual.constraints.some(r => constraintMatches(r, item.label, actual.dialect))) missing.push(item.name);
    if (!actual.indexes.some(r => indexMatches(r, item.label, "key", actual.dialect))) missing.push(`${item.label}.key index`);
    if (!actual.indexes.some(r => indexMatches(r, item.label, "tenantValue", actual.dialect))) missing.push(item.scope);
  }
  return {valid: missing.length === 0, constraints: actual.constraints.map(r => String(r.name ?? `${r.label}.key`)),
    indexes: actual.indexes.map(r => String(r.name ?? `${r.label}.${r.property}`)), missing};
}
export async function assertManagedGraphCompatibility(adapter: GraphAdapter): Promise<void> {
  if (!await adapter.isConnected()) throw new GraphDatabaseError("Managed graph is unavailable.", "GRAPH_UNAVAILABLE");
  const result = await verifyGraphSchema(adapter);
  if (!result.valid) throw new GraphDatabaseError("Managed-v2 graph schema is missing. Run explicit initializeGraphSchema and initialGraphSync with an administrator rebuild transport.", "GRAPH_SCHEMA_MIGRATION_REQUIRED");
}
export async function initializeGraphSchema(adapter: GraphAdapter): Promise<void> {
  // Inspection errors always propagate; a network/auth/syntax error is never already-exists.
  const actual = await inspect(adapter);
  await verifyGraphSchema(adapter); // Detect conflicting fixed names before any creation.
  for (const item of names) {
    if (!actual.constraints.some(r => constraintMatches(r, item.label, actual.dialect))) await adapter.query(actual.dialect === "neo4j" ?
      `CREATE CONSTRAINT ${item.name} IF NOT EXISTS FOR (n:${item.label}) REQUIRE n.key IS UNIQUE` :
      `CREATE CONSTRAINT ON (n:${item.label}) ASSERT n.key IS UNIQUE`);
    if (actual.dialect === "memgraph" && !actual.indexes.some(r => indexMatches(r, item.label, "key", actual.dialect)))
      await adapter.query(`CREATE INDEX ON :${item.label}(key)`);
    if (!actual.indexes.some(r => indexMatches(r, item.label, "tenantValue", actual.dialect))) await adapter.query(actual.dialect === "neo4j" ?
      `CREATE INDEX ${item.scope} IF NOT EXISTS FOR (n:${item.label}) ON (n.tenantValue)` : `CREATE INDEX ON :${item.label}(tenantValue)`);
  }
  await assertManagedGraphCompatibility(adapter);
}
export async function dropGraphSchema(adapter: GraphAdapter, options?: {managedVersion: 2}): Promise<void> {
  if (options?.managedVersion !== 2) throw new GraphDatabaseError("Global schema deletion is retired. Explicitly select managedVersion:2 to drop only fixed Cortex-v2 objects.", "GRAPH_SCHEMA_MIGRATION_REQUIRED");
  const actual = await inspect(adapter);
  await verifyGraphSchema(adapter); // All named shapes are checked before effects.
  for (const item of names) {
    if (actual.dialect === "neo4j") {
      if (actual.constraints.some(r => r.name === item.name && constraintMatches(r, item.label, actual.dialect)))
        await adapter.query(`DROP CONSTRAINT ${item.name} IF EXISTS`);
      if (actual.indexes.some(r => r.name === item.scope && indexMatches(r, item.label, "tenantValue", actual.dialect)))
        await adapter.query(`DROP INDEX ${item.scope} IF EXISTS`);
    } else {
      if (actual.constraints.some(r => constraintMatches(r, item.label, actual.dialect))) await adapter.query(`DROP CONSTRAINT ON (n:${item.label}) ASSERT n.key IS UNIQUE`);
      for (const property of ["key", "tenantValue"]) if (actual.indexes.some(r => indexMatches(r, item.label, property, actual.dialect)))
        await adapter.query(`DROP INDEX ON :${item.label}(${property})`);
    }
  }
}

/**
 * Graph Database Integration - Type Definitions
 *
 * Defines interfaces for graph database operations, supporting Neo4j, Memgraph,
 * and other Cypher-compatible graph databases.
 */

/**
 * Graph node representation
 */
export interface GraphNode {
  /** Node label (e.g., 'Context', 'Memory', 'Fact') */
  label: string;

  /** Node properties (key-value pairs) */
  properties: Record<string, unknown>;

  /** Optional node ID (set by graph database after creation) */
  id?: string;
}

/**
 * Graph edge (relationship) representation
 */
export interface GraphEdge {
  /** Relationship type (e.g., 'CHILD_OF', 'MENTIONS', 'SENT_TO') */
  type: string;

  /** Source node ID */
  from: string;

  /** Target node ID */
  to: string;

  /** Optional relationship properties */
  properties?: Record<string, unknown>;

  /** Optional edge ID (set by graph database after creation) */
  id?: string;
}

/**
 * Cypher query with parameters
 */
export interface GraphQuery {
  /** Cypher query string */
  cypher: string;

  /** Query parameters (for parameterized queries) */
  params?: Record<string, unknown>;
}

/**
 * Path between nodes in graph
 */
export interface GraphPath {
  /** Nodes in the path */
  nodes: GraphNode[];

  /** Relationships in the path */
  relationships: GraphEdge[];

  /** Path length (number of hops) */
  length: number;
}

/**
 * Graph database connection configuration
 */
export interface GraphConnectionConfig {
