/**
 * Default priority for unknown operations
 */
export const DEFAULT_PRIORITY: Priority = "normal";

/**
 * Get priority for an operation name
 *
 * Supports exact matches and wildcard patterns (e.g., "graphSync:*")
 *
 * @param operationName - The operation name (e.g., "memory:remember")
 * @returns The priority level for the operation
 */
export function getPriority(operationName: string): Priority {
  // Try exact match first
  if (operationName in OPERATION_PRIORITIES) {
    return OPERATION_PRIORITIES[operationName];
  }

  // Try wildcard match (e.g., "graphSync:*" matches "graphSync:anything")
  const [namespace] = operationName.split(":");
  const wildcardKey = `${namespace}:*`;

  if (wildcardKey in OPERATION_PRIORITIES) {
    return OPERATION_PRIORITIES[wildcardKey];
  }

  // Return default priority
  return DEFAULT_PRIORITY;
}

/**
 * Check if an operation is critical (should never be dropped)
 */
export function isCritical(operationName: string): boolean {
  return getPriority(operationName) === "critical";
}

/**
 * Get all operation names for a given priority level
 */
export function getOperationsByPriority(priority: Priority): string[] {
  return Object.entries(OPERATION_PRIORITIES)
    .filter(([_, p]) => p === priority)
    .map(([name]) => name);
}

/**
 * Priority Queue
 *
 * In-memory queue that orders requests by priority level.
 * Higher priority requests are processed before lower priority ones.
 *
 * Features:
 * - Separate queues per priority level
 * - Configurable max size per priority
 * - Starvation prevention (optional aging)
 * - FIFO within same priority level
 */

import {
  DEFAULT_QUEUE_SIZES,
  PRIORITY_ORDER,
  QueueFullError,
  type Priority,
  type QueueConfig,
  type QueuedRequest,
  type QueueMetrics,
} from "./types";

export class PriorityQueue<T = unknown> {
  private queues: Map<Priority, Array<QueuedRequest<T>>>;
  private limits: Record<Priority, number>;

  // Metrics tracking
  private processed: number = 0;
  private dropped: number = 0;

  constructor(config: QueueConfig = {}) {
    // Initialize queue for each priority level
    this.queues = new Map();
    for (const priority of PRIORITY_ORDER) {
      this.queues.set(priority, []);
    }

    // Merge limits with defaults
    this.limits = { ...DEFAULT_QUEUE_SIZES, ...config.maxSize };
  }

  /**
   * Add a request to the queue
   *
   * @param request The request to queue
   * @returns true if queued, false if queue was full
   * @throws QueueFullError if queue is full for the given priority
   */
  enqueue(request: QueuedRequest<T>): boolean {
    const queue = this.queues.get(request.priority)!;
    const limit = this.limits[request.priority];

    // Check if queue is full
    if (queue.length >= limit) {
      this.dropped++;
      throw new QueueFullError(request.priority, queue.length);
    }

    queue.push(request);
    return true;
  }

  /**
   * Try to add a request without throwing
   *
   * @param request The request to queue
   * @returns true if queued, false if queue was full
   */
  tryEnqueue(request: QueuedRequest<T>): boolean {
    const queue = this.queues.get(request.priority)!;
    const limit = this.limits[request.priority];

    if (queue.length >= limit) {
      this.dropped++;
      return false;
    }

    queue.push(request);
    return true;
  }

  /**
   * Remove and return the highest priority request
   *
   * @returns The next request to process, or undefined if queue is empty
   */
  dequeue(): QueuedRequest<T> | undefined {
    // Process in priority order (critical first, background last)
    for (const priority of PRIORITY_ORDER) {
      const queue = this.queues.get(priority)!;

      if (queue.length > 0) {
        this.processed++;
        return queue.shift();
      }
    }

    return undefined;
  }

  /**
   * Peek at the highest priority request without removing it
   *
   * @returns The next request that would be dequeued, or undefined if empty
   */
  peek(): QueuedRequest<T> | undefined {
    for (const priority of PRIORITY_ORDER) {
      const queue = this.queues.get(priority)!;

      if (queue.length > 0) {
        return queue[0];
      }
    }

    return undefined;
  }

  /**
   * Get total number of queued requests
   */
  size(): number {
    let total = 0;
    for (const queue of this.queues.values()) {
      total += queue.length;
    }
    return total;
  }

  /**
   * Get queue size broken down by priority
   */
  sizeByPriority(): Record<Priority, number> {
    const result: Record<Priority, number> = {
      critical: 0,
      high: 0,
      normal: 0,
      low: 0,
      background: 0,
    };

    for (const [priority, queue] of this.queues.entries()) {
      result[priority] = queue.length;
    }

    return result;
  }

  /**
   * Check if the queue is empty
   */
  isEmpty(): boolean {
    return this.size() === 0;
  }

  /**
   * Check if a specific priority queue has capacity
   */
  hasCapacity(priority: Priority): boolean {
    const queue = this.queues.get(priority)!;
    return queue.length < this.limits[priority];
  }

  /**
   * Get the age of the oldest request in the queue (ms)
   */
  getOldestRequestAge(): number | undefined {
    let oldest: number | undefined;
    const now = Date.now();

    for (const queue of this.queues.values()) {
      if (queue.length > 0) {
        const age = now - queue[0].queuedAt;
        if (oldest === undefined || age > oldest) {
          oldest = age;
        }
      }
    }

    return oldest;
  }

  /**
   * Remove all expired requests (older than maxAge)
   *
   * @param maxAgeMs Maximum age in milliseconds
   * @returns Number of requests removed
   */
  removeExpired(maxAgeMs: number): number {
    const now = Date.now();
    let removed = 0;

    for (const [_, queue] of this.queues.entries()) {
      const toRemove: number[] = [];

      for (let i = 0; i < queue.length; i++) {
        if (now - queue[i].queuedAt > maxAgeMs) {
          toRemove.push(i);
        }
      }

      // Remove from end to preserve indices
      for (let i = toRemove.length - 1; i >= 0; i--) {
        const request = queue.splice(toRemove[i], 1)[0];
        request.reject(
          new Error(`Request expired after ${maxAgeMs}ms in queue`),
        );
        removed++;
      }
    }

    return removed;
  }

  /**
   * Cancel a specific request by ID
   *
   * @param requestId The request ID to cancel
   * @returns true if found and cancelled, false otherwise
   */
  cancel(requestId: string): boolean {
    for (const [_, queue] of this.queues.entries()) {
      const index = queue.findIndex((r) => r.id === requestId);

      if (index !== -1) {
        const [request] = queue.splice(index, 1);
        request.reject(new Error("Request cancelled"));
        return true;
      }
    }

    return false;
  }

  /**
   * Get current metrics
   */
  getMetrics(): QueueMetrics {
    return {
      total: this.size(),
      byPriority: this.sizeByPriority(),
      processed: this.processed,
      dropped: this.dropped,
      oldestRequestAgeMs: this.getOldestRequestAge(),
    };
  }

  /**
   * Clear all queues and reject all pending requests
   */
  clear(): void {
    for (const [_, queue] of this.queues.entries()) {
      while (queue.length > 0) {
        const request = queue.shift()!;
        request.reject(new Error("Queue cleared"));
      }
    }
  }

  /**
   * Reset metrics (but keep queued requests)
   */
  resetMetrics(): void {
    this.processed = 0;
    this.dropped = 0;
  }
}

/**
 * Async Semaphore Concurrency Limiter
 *
 * Limits the number of concurrent in-flight requests using a semaphore pattern.
 * Requests beyond the limit wait in a queue until a permit becomes available.
 *
 * Behavior:
 * - maxConcurrent permits available at any time
 * - Requests acquire a permit before executing, release after
 * - Excess requests wait in a queue (up to queueSize)
 * - Optional timeout prevents indefinite waiting
 */

import {
  AcquireTimeoutError,
  DEFAULT_CONCURRENCY_CONFIG,
  type ConcurrencyConfig,
  type ConcurrencyMetrics,
  type SemaphorePermit,
} from "./types";

interface WaitingRequest {
  resolve: (permit: SemaphorePermit) => void;
  reject: (error: Error) => void;
  timeoutId?: ReturnType<typeof setTimeout>;
}

export class Semaphore {
  private availablePermits: number;
  private readonly maxPermits: number;
  private readonly queueLimit: number;
  private readonly defaultTimeout: number;
  private waiting: WaitingRequest[] = [];

  // Metrics tracking
  private maxReached: number = 0;
  private timeouts: number = 0;

  constructor(config: ConcurrencyConfig = {}) {
    const merged = { ...DEFAULT_CONCURRENCY_CONFIG, ...config };
    this.maxPermits = merged.maxConcurrent;
    this.queueLimit = merged.queueSize;
    this.defaultTimeout = merged.timeout;
    this.availablePermits = this.maxPermits;
  }

  /**
   * Acquire a permit, waiting if necessary
   *
   * @param timeout Maximum time to wait (ms). Uses default if not provided.
   * @returns A permit that must be released when done
   * @throws AcquireTimeoutError if timeout is reached
   * @throws Error if queue is full
   */
  async acquire(timeout?: number): Promise<SemaphorePermit> {
    // Fast path: permit available immediately
    if (this.availablePermits > 0) {
      this.availablePermits--;
      this.updateMaxReached();
      return this.createPermit();
    }

    // Check queue limit
    if (this.waiting.length >= this.queueLimit) {
      throw new Error(
        `Semaphore queue full (${this.queueLimit} requests waiting)`,
      );
    }

    // Wait for a permit
    const effectiveTimeout = timeout ?? this.defaultTimeout;

    return new Promise<SemaphorePermit>((resolve, reject) => {
      const request: WaitingRequest = { resolve, reject };

      // Set timeout if specified
      if (effectiveTimeout > 0) {
        request.timeoutId = setTimeout(() => {
          // Remove from queue
          const index = this.waiting.indexOf(request);
          if (index !== -1) {
            this.waiting.splice(index, 1);
          }

          this.timeouts++;
          reject(
            new AcquireTimeoutError(effectiveTimeout, this.waiting.length),
          );
        }, effectiveTimeout);
      }

      this.waiting.push(request);
    });
  }

  /**
   * Try to acquire a permit without waiting
   *
   * @returns A permit if available, undefined otherwise
   */
  tryAcquire(): SemaphorePermit | undefined {
    if (this.availablePermits > 0) {
      this.availablePermits--;
      this.updateMaxReached();
      return this.createPermit();
    }

    return undefined;
  }

  /**
   * Create a permit object with release function
   */
  private createPermit(): SemaphorePermit {
    let released = false;

    return {
      release: () => {
        if (released) {
          console.warn("Semaphore permit released multiple times");
          return;
        }

        released = true;
        this.release();
      },
    };
  }

  /**
   * Release a permit back to the semaphore
   * (Called internally by permit.release())
   */
  private release(): void {
    // If there are waiting requests, give permit to next in line
    if (this.waiting.length > 0) {
      const next = this.waiting.shift()!;

      // Clear timeout if set
      if (next.timeoutId) {
        clearTimeout(next.timeoutId);
      }

      // Give them a new permit (don't increase availablePermits)
      this.updateMaxReached();
      next.resolve(this.createPermit());
    } else {
      // No waiting requests, return permit to pool
      this.availablePermits++;
    }
  }

  /**
   * Update max concurrent reached metric
   */
  private updateMaxReached(): void {
    const active = this.maxPermits - this.availablePermits;
    if (active > this.maxReached) {
      this.maxReached = active;
    }
  }

  /**
   * Get number of currently active (acquired) permits
   */
  getActiveCount(): number {
    return this.maxPermits - this.availablePermits;
  }

  /**
   * Get number of requests waiting for a permit
   */
  getWaitingCount(): number {
    return this.waiting.length;
  }

  /**
   * Get available permits
   */
  getAvailableCount(): number {
    return this.availablePermits;
  }

  /**
   * Get current metrics
   */
  getMetrics(): ConcurrencyMetrics {
    return {
      active: this.getActiveCount(),
      waiting: this.waiting.length,
      maxReached: this.maxReached,
      timeouts: this.timeouts,
    };
  }

  /**
   * Reset semaphore to initial state
   * WARNING: This will reject all waiting requests
   */
  reset(): void {
    // Reject all waiting requests
    const waitingCopy = [...this.waiting];
    this.waiting = [];

    for (const request of waitingCopy) {
      if (request.timeoutId) {
        clearTimeout(request.timeoutId);
      }
      request.reject(new Error("Semaphore reset"));
    }

    // Reset permits and metrics
    this.availablePermits = this.maxPermits;
    this.maxReached = 0;
    this.timeouts = 0;
  }
}

/**
 * Token Bucket Rate Limiter
 *
 * Implements the classic token bucket algorithm to smooth burst traffic.
 * Tokens are consumed on each request and refill over time.
 *
 * Behavior:
 * - Bucket starts full (bucketSize tokens)
 * - Each request consumes 1 token
 * - Tokens refill at refillRate per second
 * - Burst traffic up to bucketSize passes immediately
 * - Sustained traffic is smoothed to refillRate
 */

import {
  DEFAULT_RATE_LIMITER_CONFIG,
  RateLimitExceededError,
  type RateLimiterConfig,
  type RateLimiterMetrics,
} from "./types";

export class TokenBucket {
  private tokens: number;
  private lastRefill: number;
  private readonly bucketSize: number;
  private readonly refillRate: number;

  // Metrics tracking
  private requestsThrottled: number = 0;
  private totalWaitTimeMs: number = 0;

  constructor(config: RateLimiterConfig = {}) {
    const merged = { ...DEFAULT_RATE_LIMITER_CONFIG, ...config };
    this.bucketSize = merged.bucketSize;
    this.refillRate = merged.refillRate;
    this.tokens = this.bucketSize; // Start with full bucket
    this.lastRefill = Date.now();
  }

  /**
   * Refill tokens based on time elapsed since last refill
   */
  private refill(): void {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    const tokensToAdd = (elapsed / 1000) * this.refillRate;

    this.tokens = Math.min(this.bucketSize, this.tokens + tokensToAdd);
    this.lastRefill = now;
  }

  /**
   * Try to acquire a token without waiting
   *
   * @returns true if token was acquired, false if bucket is empty
   */
  tryAcquire(): boolean {
    this.refill();

    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }

    return false;
  }

  /**
   * Acquire a token, waiting if necessary
   *
   * @param timeout Maximum time to wait (ms). If not provided, waits indefinitely.
   * @throws RateLimitExceededError if timeout is reached
   */
  async acquire(timeout?: number): Promise<void> {
    this.refill();

    // Fast path: token available immediately
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return;
    }

    // Calculate time until next token is available
    const tokensNeeded = 1 - this.tokens;
    const waitTimeMs = (tokensNeeded / this.refillRate) * 1000;

    // Check timeout
    if (timeout !== undefined && waitTimeMs > timeout) {
      throw new RateLimitExceededError(
        Math.floor(this.tokens),
        Math.ceil(waitTimeMs),
      );
    }

    // Track throttling metrics
    this.requestsThrottled++;
    this.totalWaitTimeMs += waitTimeMs;

    // Wait for token to become available
    await this.sleep(waitTimeMs);

    // Refill and consume token
    this.refill();
    this.tokens -= 1;
  }

  /**
   * Get the number of tokens currently available
   */
  getAvailableTokens(): number {
    this.refill();
    return Math.floor(this.tokens);
  }

  /**
   * Get time until next token is available (ms)
   */
  getTimeUntilNextToken(): number {
    this.refill();

    if (this.tokens >= 1) {
      return 0;
    }

    const tokensNeeded = 1 - this.tokens;
    return Math.ceil((tokensNeeded / this.refillRate) * 1000);
  }

  /**
   * Get current metrics
   */
  getMetrics(): RateLimiterMetrics {
    this.refill();

    return {
      tokensAvailable: Math.floor(this.tokens),
      requestsThrottled: this.requestsThrottled,
      avgWaitTimeMs:
        this.requestsThrottled > 0
          ? this.totalWaitTimeMs / this.requestsThrottled
          : 0,
    };
  }

  /**
   * Reset the bucket to full and clear metrics
   */
  reset(): void {
    this.tokens = this.bucketSize;
    this.lastRefill = Date.now();
    this.requestsThrottled = 0;
    this.totalWaitTimeMs = 0;
  }

  /**
   * Sleep utility
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

