/**
 * List agents with optional filters
 */
export const list = query({
  args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    status: v.optional(
      v.union(
        v.literal("active"),
        v.literal("inactive"),
        v.literal("archived"),
      ),
    ),
    limit: v.optional(v.number()),
    offset: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    let query;

    if (args.status) {
      query = ctx.db
        .query("agents")
        .withIndex("by_status", (q) => q.eq("status", args.status!))
        .order("desc");
    } else {
      query = ctx.db.query("agents").withIndex("by_registered").order("desc");
    }

    query = query.filter((q) => q.and(q.eq(q.field("tenantId"), args.tenantId), ...(args.memorySpaceId === undefined ? [] : [q.eq(q.field("memorySpaceId"), args.memorySpaceId)])));
    if (args.offset) {
      // Skip first N results
      const allResults = await query.filter((q) => q.and(q.eq(q.field("tenantId"), args.tenantId), ...(args.memorySpaceId === undefined ? [] : [q.eq(q.field("memorySpaceId"), args.memorySpaceId)]))).collect();
      const sliced = allResults.slice(
        args.offset,
        args.offset + (args.limit || 100),
      );
      return sliced;
    }

    if (args.limit) {
      return await query.take(args.limit);
    }

    return await query.take(100); // Default limit
  },
});

