/**
 * Register an agent
 */
export const register = mutation({
  args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    agentId: v.string(),
    name: v.string(),
    description: v.optional(v.string()),
    metadata: v.optional(v.any()),
    config: v.optional(v.any()),
  },
  handler: async (ctx, args) => {
    // Check if agent already registered
    const existing = await ctx.db
      .query("agents")
      .withIndex("by_agentId", (q) => q.eq("agentId", args.agentId))
      .filter((q) => q.and(q.eq(q.field("tenantId"), args.tenantId), ...(args.memorySpaceId === undefined ? [] : [q.eq(q.field("memorySpaceId"), args.memorySpaceId)]))).first();

    if (existing) {
      throw new ConvexError("AGENT_ALREADY_REGISTERED");
    }

    const now = Date.now();

    const agentId = await ctx.db.insert("agents", {
      agentId: args.agentId,
      tenantId: args.tenantId,
      memorySpaceId: args.memorySpaceId,
      name: args.name,
      description: args.description,
      metadata: args.metadata || {},
      config: args.config || {},
      status: "active",
      registeredAt: now,
      updatedAt: now,
    });

    const agent = await ctx.db.get(agentId);
    if (!agent) throw new ConvexError("AGENT_NOT_REGISTERED");
    return agent;
  },
});

/**
 * Update agent registration
 */
export const update = mutation({
  args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    agentId: v.string(),
    name: v.optional(v.string()),
    description: v.optional(v.string()),
    metadata: v.optional(v.any()),
    config: v.optional(v.any()),
    status: v.optional(
      v.union(
        v.literal("active"),
        v.literal("inactive"),
        v.literal("archived"),
      ),
    ),
  },
  handler: async (ctx, args) => {
    const agent = await ctx.db
      .query("agents")
      .withIndex("by_agentId", (q) => q.eq("agentId", args.agentId))
      .filter((q) => q.and(q.eq(q.field("tenantId"), args.tenantId), ...(args.memorySpaceId === undefined ? [] : [q.eq(q.field("memorySpaceId"), args.memorySpaceId)]))).first();

    if (!agent) {
      throw new ConvexError("AGENT_NOT_REGISTERED");
    }

    // Build update object
    const updates: any = {
      updatedAt: Date.now(),
    };

    if (args.name !== undefined) updates.name = args.name;
    if (args.description !== undefined) updates.description = args.description;
    if (args.metadata !== undefined) updates.metadata = args.metadata;
    if (args.config !== undefined) updates.config = args.config;
    if (args.status !== undefined) updates.status = args.status;

    await ctx.db.patch(agent._id, updates);

    const updated = await ctx.db.get(agent._id);
    if (!updated) throw new ConvexError("AGENT_NOT_REGISTERED");
    return updated;
  },
});

/**
 * Update multiple agents by IDs
 *
 * Note: Filtering is handled in the SDK layer - this mutation receives
 * specific agent IDs to update.
 */
export const updateMany = mutation({
  args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.optional(v.string()),
    agentIds: v.array(v.string()),
    name: v.optional(v.string()),
    description: v.optional(v.string()),
    metadata: v.optional(v.any()),
    config: v.optional(v.any()),
  },
  handler: async (ctx, args) => {
    if (!args.agentIds || args.agentIds.length === 0) {
      return { updated: 0, agentIds: [] };
    }

    // Build update object (only include provided fields)
    const updates: Record<string, unknown> = {
      updatedAt: Date.now(),
    };

    if (args.name !== undefined) updates.name = args.name;
    if (args.description !== undefined) updates.description = args.description;
    if (args.metadata !== undefined) updates.metadata = args.metadata;
    if (args.config !== undefined) updates.config = args.config;

    const updatedAgentIds: string[] = [];

    for (const agentId of args.agentIds) {
      const agent = await ctx.db
        .query("agents")
        .withIndex("by_agentId", (q) => q.eq("agentId", agentId))
        .filter((q) => q.and(q.eq(q.field("tenantId"), args.tenantId), ...(args.memorySpaceId === undefined ? [] : [q.eq(q.field("memorySpaceId"), args.memorySpaceId)]))).first();

      if (agent) {
        await ctx.db.patch(agent._id, updates);
        updatedAgentIds.push(agentId);
      }
    }

    return {
      updated: updatedAgentIds.length,
      agentIds: updatedAgentIds,
    };
  },
});

