function counts(events: Doc<"factHistory">[]) {
  const result = {
    CREATE: 0,
    UPDATE: 0,
    SUPERSEDE: 0,
    DELETE: 0,
    total: events.length,
  };
  for (const event of events) result[event.action]++;
  return result;
}
export const countByAction = query({
