    const csv = [headers.join(","), ...rows.map((r) => r.map(cell => `"${cell.replace(/"/g, '""')}"`).join(","))].join("\n");

    return {
      format: "csv",
      data: csv,
      count: memories.length,
      exportedAt: Date.now(),
