/**
 * List memory spaces with pagination and sorting
 */
export const list = query({
  args: {
    type: v.optional(
      v.union(
        v.literal("personal"),
        v.literal("team"),
        v.literal("project"),
        v.literal("custom"),
      ),
    ),
    status: v.optional(v.union(v.literal("active"), v.literal("archived"))),
    participant: v.optional(v.string()),
    limit: v.optional(v.number()),
    offset: v.optional(v.number()),
    sortBy: v.optional(
      v.union(
        v.literal("createdAt"),
        v.literal("updatedAt"),
        v.literal("name"),
      ),
    ),
    sortOrder: v.optional(v.union(v.literal("asc"), v.literal("desc"))),
    tenantId: v.optional(v.string()), // Multi-tenancy: SaaS platform isolation
  },
  handler: async (ctx, args) => {
    validateDomainScope(args.tenantId);
    let spaces = await ctx.db.query("memorySpaces").withIndex("by_tenantId", q => q.eq("tenantId", args.tenantId)).collect();


    // Apply filters
    if (args.type) {
      spaces = spaces.filter((s) => s.type === args.type);
    }

    if (args.status) {
      spaces = spaces.filter((s) => s.status === args.status);
    }

    if (args.participant) {
      spaces = spaces.filter((s) =>
        s.participants.some((p) => p.id === args.participant),
      );
    }

    // Get total before pagination
    const total = spaces.length;

    // Sort
    const sortBy = args.sortBy || "createdAt";
    const sortOrder = args.sortOrder || "desc";

    spaces.sort((a, b) => {
      let aVal: string | number | undefined;
      let bVal: string | number | undefined;

      if (sortBy === "name") {
        aVal = a.name || "";
        bVal = b.name || "";
      } else {
        aVal = a[sortBy];
        bVal = b[sortBy];
      }

      if (aVal === undefined) aVal = sortBy === "name" ? "" : 0;
      if (bVal === undefined) bVal = sortBy === "name" ? "" : 0;

      if (sortOrder === "asc") {
        return aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      } else {
        return aVal > bVal ? -1 : aVal < bVal ? 1 : 0;
      }
    });

    // Apply pagination
    const offset = args.offset || 0;
    const limit = args.limit || 100;
    const paginatedSpaces = spaces.slice(offset, offset + limit);

    return {
      spaces: paginatedSpaces,
      total,
      hasMore: offset + limit < total,
      offset,
    };
  },
});

