/**
 * Search memory spaces by name or metadata
 */
export const search = query({
  args: {
    tenantId: v.optional(v.string()),
    query: v.string(),
    type: v.optional(
      v.union(
        v.literal("personal"),
        v.literal("team"),
        v.literal("project"),
        v.literal("custom"),
      ),
    ),
    status: v.optional(v.union(v.literal("active"), v.literal("archived"))),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    validateDomainScope(args.tenantId);
    let spaces = await ctx.db.query("memorySpaces").withIndex("by_tenantId", q => q.eq("tenantId", args.tenantId)).collect();

    // Apply type and status filters
    if (args.type) {
      spaces = spaces.filter((s) => s.type === args.type);
    }
    if (args.status) {
      spaces = spaces.filter((s) => s.status === args.status);
    }

    // Text search across name and metadata
    const queryLower = args.query.toLowerCase();
    spaces = spaces.filter((space) => {
      // Search in name
      if (space.name && space.name.toLowerCase().includes(queryLower)) {
        return true;
      }

      // Search in memorySpaceId
      if (space.memorySpaceId.toLowerCase().includes(queryLower)) {
        return true;
      }

      // Search in metadata (stringify and search)
      if (space.metadata) {
        const metadataStr = JSON.stringify(convexToJson(space.metadata)).toLowerCase();
        if (metadataStr.includes(queryLower)) {
          return true;
        }
      }

      return false;
    });

    // Limit results
    return spaces.slice(0, args.limit || 50);
  },
});

/**
 * Update participants (combined add/remove)
 */
export const updateParticipants = graphMutation({
  args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.string(),
    add: v.optional(
      v.array(
        v.object({
          id: v.string(),
          type: v.string(),
          joinedAt: v.number(),
        }),
      ),
    ),
    remove: v.optional(v.array(v.string())), // Participant IDs to remove
  },
  handler: async (ctx, args) => {
    const space = await scopedSpace(ctx, args.tenantId, args.memorySpaceId);

    if (!space) {
      throw new ConvexError("MEMORYSPACE_NOT_FOUND");
    }

    let updatedParticipants = [...space.participants];

    // Remove participants
    if (args.remove && args.remove.length > 0) {
      updatedParticipants = updatedParticipants.filter(
        (p) => !args.remove!.includes(p.id),
      );
    }

    // Add new participants
    if (args.add && args.add.length > 0) {
      for (const newParticipant of args.add) {
        // Don't add duplicates
        if (!updatedParticipants.some((p) => p.id === newParticipant.id)) {
          updatedParticipants.push(newParticipant);
        }
      }
    }

    await reconcileRow(ctx, space._id, {
      participants: updatedParticipants,
      updatedAt: Date.now(),
    });

    return await ctx.db.get(space._id);
  },
});

/**
 * Purge all memory spaces (TEST/DEV ONLY)
 */
export const purgeAll = graphMutation({
  args: {},
  handler: async (ctx) => {
    // Safety check: Only allow in test/dev environments
    const siteUrl = process.env.CONVEX_SITE_URL || "";
    const isLocal =
      siteUrl.includes("localhost") || siteUrl.includes("127.0.0.1");
    const isDevDeployment =
      siteUrl.includes(".convex.site") ||
      siteUrl.includes("dev-") ||
      siteUrl.includes("convex.cloud");
    const isTestEnv =
      process.env.NODE_ENV === "test" ||
      process.env.CONVEX_ENVIRONMENT === "test";

    if (!isLocal && !isDevDeployment && !isTestEnv) {
      throw new Error(
        "PURGE_DISABLED_IN_PRODUCTION: purgeAll is only available in test/dev environments.",
      );
    }

    const allSpaces = await ctx.db.query("memorySpaces").collect();

    for (const space of allSpaces) {
      await markDeletedRow(ctx, space._id);
    }

    return { deleted: allSpaces.length };
  },
});

/** Internal deployment administration of legacy rows; runtime data remains protected. */
import { graphMutation } from "../lib/graphSync";
import { reconcileRow, captureInsertedRow, markDeletedRow } from "../lib/referenceLifecycle";
/**
 * Cortex SDK - Mutable Store API (Layer 1c)
 *
 * ACID-compliant mutable storage for live, frequently-changing data
 * Namespaces: inventory, config, counters, sessions, state, etc.
 */

import { ConvexError, v } from "convex/values";
import { operatorQuery as query } from "../lib/operatorBoundary";

// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Mutations (Write Operations)
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

/**
 * Set a key to a value (creates or overwrites)
 */
export const set = graphMutation({
  args: {
    namespace: v.string(),
    key: v.string(),
    value: v.any(),
    userId: v.optional(v.string()),
    tenantId: v.optional(v.string()), // Multi-tenancy: SaaS platform isolation
    metadata: v.optional(v.any()),
  },
  handler: async (ctx, args) => {
    const now = Date.now();

    // Check if entry exists - must match both namespace/key AND tenantId for proper isolation
    let existing;
    if (args.tenantId) {
      // With tenant isolation: look for tenant-specific entry
      existing = await ctx.db
        .query("mutable")
        .withIndex("by_tenant_namespace_key", (q) =>
          q
            .eq("tenantId", args.tenantId!)
            .eq("namespace", args.namespace)
            .eq("key", args.key),
        )
        .first();
    } else {
      // Without tenant: fallback to global namespace/key lookup
      // SECURITY: Must verify the matched record has no tenantId to prevent cross-tenant access
      const candidate = await ctx.db
        .query("mutable")
        .withIndex("by_namespace_key", (q) =>
          q.eq("namespace", args.namespace).eq("key", args.key),
        )
        .first();
      // Only match if the record is truly global (no tenantId)
      existing = candidate && !candidate.tenantId ? candidate : null;
    }

    if (existing) {
      // Update existing
      await reconcileRow(ctx, existing._id, {
        value: args.value,
        userId: args.userId !== undefined ? args.userId : existing.userId,
        metadata:
          args.metadata !== undefined ? args.metadata : existing.metadata,
        updatedAt: now,
      });

      return await ctx.db.get(existing._id);
    }
    // Create new
    const _id = await captureInsertedRow(ctx, "mutable", {
      namespace: args.namespace,
      key: args.key,
      value: args.value,
      userId: args.userId,
      tenantId: args.tenantId, // Store tenantId
      metadata: args.metadata,
      createdAt: now,
      updatedAt: now,
    });

    return await ctx.db.get(_id);
  },
});

/**
 * Atomic update using updater function
 */
export const update = graphMutation({
  args: {
    namespace: v.string(),
    key: v.string(),
    // Note: updater function is passed as serialized code in the actual implementation
    // For now, we'll handle simple operations
    operation: v.union(
      v.literal("increment"),
      v.literal("decrement"),
      v.literal("append"),
      v.literal("custom"),
    ),
    operand: v.optional(v.any()),
    tenantId: v.optional(v.string()), // Multi-tenancy: SaaS platform isolation
  },
  handler: async (ctx, args) => {
    let existing;
    if (args.tenantId) {
      // Tenant-isolated lookup
      existing = await ctx.db
        .query("mutable")
        .withIndex("by_tenant_namespace_key", (q) =>
          q
            .eq("tenantId", args.tenantId!)
            .eq("namespace", args.namespace)
            .eq("key", args.key),
        )
        .first();
    } else {
      // Global namespace/key lookup for non-tenant records only
      // SECURITY: Must verify the matched record has no tenantId to prevent cross-tenant updates
      const candidate = await ctx.db
        .query("mutable")
        .withIndex("by_namespace_key", (q) =>
          q.eq("namespace", args.namespace).eq("key", args.key),
        )
        .first();
      // Only match if the record is truly global (no tenantId)
      existing = candidate && !candidate.tenantId ? candidate : null;
    }

    if (!existing) {
      throw new ConvexError("MUTABLE_KEY_NOT_FOUND");
    }

    let newValue = existing.value;

    // Apply operation
    switch (args.operation) {
