export const getChangesByTimeRange = query({
  args: {
    tenantId: v.optional(v.string()),
    memorySpaceId: v.string(),
    after: v.optional(v.number()),
    before: v.optional(v.number()),
    action: v.optional(
      v.union(
        v.literal("CREATE"),
        v.literal("UPDATE"),
        v.literal("SUPERSEDE"),
        v.literal("DELETE"),
      ),
    ),
    limit: v.optional(v.number()),
