    role: Role,
    slot: string,
    target: Primary,
    logical: unknown,
    authority = false,
    physical?: unknown,
    space: string | undefined = tenantSpace,
    qualifier?: string,
  ) => {
    if (typeof logical !== "string" && typeof physical !== "string") return;
    slots.push({
      role,
      slot,
      table: target,
      logical: text(logical),
      physical: text(physical),
      space,
      qualifier,
      authority,
