      "conversation",
      "conversationRef",
      "conversations",
      ref("conversationRef").conversationId,
      true,
    );
    add(
      "context-parent",
      "parentId",
      "contexts",
      row.parentId,
      false,
      undefined,
      undefined,
    );
    add(
      "context-root",
      "rootId",
      "contexts",
      row.rootId,
      false,
      undefined,
      undefined,
    );
