        "context-child",
        "childIds:" + x,
        "contexts",
        x,
        false,
        undefined,
        undefined,
      ),
    );
    strings(row.participants).forEach((x) =>
      add(
        "participant-space",
        "participants:" + x,
        "memorySpaces",
        x,
        false,
        undefined,
        undefined,
      ),
    );
    arr(row.grantedAccess)
      .map(obj)
      .forEach((x) =>
        add(
          "access-space",
          "grantedAccess:" + String(x.memorySpaceId),
          "memorySpaces",
          x.memorySpaceId,
          false,
          undefined,
          undefined,
        ),
      );
  }
  if (table === "artifacts") {
    add(
      "conversation",
      "conversationRef",
      "conversations",
      ref("conversationRef").conversationId,
      true,
    );
    arr(row.memoryRefs)
      .map(obj)
      .forEach((x) =>
        add(
          "memory",
          "memoryRefs:" + String(x.memoryId),
          "memories",
          x.memoryId,
          true,
        ),
      );
    add(
      "session",
      "streamingMetadata.sessionId",
      "sessions",
      ref("streamingMetadata").sessionId,
      false,
      undefined,
      undefined,
    );
  }
  if (table === "attachments") {
    add("conversation", "conversationId", "conversations", row.conversationId);
    add("memory", "memoryId", "memories", row.memoryId);
    add("artifact", "artifactId", "artifacts", row.artifactId);
  }
  if (table === "conversationShares") {
    add(
      "share-source",
      "conversationId",
      "conversations",
      row.conversationId,
      false,
      undefined,
      text(row.sourceMemorySpaceId),
    );
    add(
      "space",
      "sourceMemorySpaceId",
      "memorySpaces",
      row.sourceMemorySpaceId,
      false,
      undefined,
      undefined,
    );
    add(
      "recipient-space",
      "recipientMemorySpaceId",
      "memorySpaces",
      row.grantType === "space" ? row.grantedTo : undefined,
      false,
      undefined,
      undefined,
    );
  }
  if (table === "conversationSnapshots")
    add(
      "snapshot-source",
      "conversationId",
      "conversations",
      row.conversationId,
    );
