      artifacts: ["by_artifactId", "artifactId"],
      attachments: ["by_attachmentId", "attachmentId"],
      memorySpaces: ["by_memorySpaceId", "memorySpaceId"],
      sessions: ["by_lifecycle_tenant_sessionId", "sessionId"],
