    await ctx.db
      .query("cortexReferenceEdges")
      .withIndex("by_source", (q) => q.eq("sourceTargetId", source._id))
      .collect()
  ).filter((e) => e.kind === "authority");
  const parent = authority.sort((a, b) =>
    (a.role + ":" + a.slot).localeCompare(b.role + ":" + b.slot),
  )[0];
