    const memory = row as unknown as WithoutSystemFields<Doc<"memories">>;
    row = {...row, vectorScopeKey: memoryVectorScopeKey(memory.tenantId, memory.memorySpaceId)};
  }
  const slots = extractReferenceSlots(table, row);
