    if (!selectedGrant || (selectedGrant.expiresAt !== undefined
      && (!Number.isFinite(selectedGrant.expiresAt) || Date.now() >= selectedGrant.expiresAt))) deny();
  } };
}
async function verifiedIdentity(ctx: RegistryCtx) {
