      vectorsThrough: vectors.indexedThrough, vectorProfileThrough, graphThrough: graphProfileThrough[DEFAULT_EMBEDDING_PROFILE.profileId] ?? 0,
      graphProfileThrough, version: scope.version + 1, updatedAt: Date.now() });
