    || profiles.some(({ profile, result }) => result.hole?.state === "missing"
      && result.indexedThrough > (scope.vectorProfileThrough?.[profile.profileId]
        ?? (profile.profileId === DEFAULT_EMBEDDING_PROFILE.profileId ? scope.vectorsThrough : 0)))) {
