    const authority = await this.authority(undefined, "read");
    const selected = authority.resourceAccess === "own"
      ? this.ctx.db.query("runtimeMemoryVectorGenerations").withIndex("by_owner", q => q.eq("tenantId", this.scope.tenantId)
