  "tool-input-available": "requested",
  "tool-call": "requested",
  "tool-approval-request": "requested",
  "tool-result": "succeeded",
  "tool-output-available": "succeeded",
  "tool-input-error": "failed",
  "tool-output-error": "failed",
  "tool-output-denied": "failed",
