            "memorySpaceId",
            "shareId",
            "conversationId",
            "sourceMemorySpaceId",
            "grantType",
            "grantedTo",
            "permissions",
            "status",
            "createdAt",
            "expiresAt",
            "maxViews",
            "viewCount",
            "revokedAt",
            "redactBefore",
            "redactSensitive",
